  const semanasNecesarias = horasPorSemana > 0 && horasPrograma > 0 ? Math.ceil(horasPrograma / horasPorSemana) : null;

  // Saber si el tipo de oferta seleccionado es "Cerrada"
  const tipoOfertaSeleccionado = tiposOferta.find(t => t._id === formData.tipo_oferta);
  const esOfertaCerrada = tipoOfertaSeleccionado?.nombre?.toLowerCase() === 'cerrada';

  // ===== RENDER PRINCIPAL =====
  return (
    <div style={styles.container}>
      {/* Header con el modo actual y botón para cambiar */}
      <div style={styles.header}>
        <h2 style={styles.title}>
          {modo === 'regular' ? '🟢 Crear Oferta Regular' : '🟠 Crear Oferta Campesena'}
        </h2>
        <button 
          onClick={onVolverAlSelector}
          style={styles.cambiarModoButton}
        >
          ← Cambiar tipo de oferta
        </button>
      </div>
      
      <form onSubmit={handleSubmit} style={styles.form}>
        
        {/* PROGRAMA DE FORMACIÓN con filtros */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Programa de Formación</h3>
          
          {/* Filtros */}
          <div style={styles.filtrosContainer}>
            <div style={styles.filtroGroup}>
              <label style={styles.label}>Filtrar por palabra:</label>
              <input
                type="text"
                placeholder="Ej: pecuaria, administrativa, etc."
                value={filtroPrograma}
                onChange={(e) => setFiltroPrograma(e.target.value)}
                style={styles.input}
              />
            </div>
            <div style={styles.filtroGroup}>
              <label style={styles.label}>Duración mínima (horas):</label>
              <input
                type="number"
                placeholder="Ej: 40"
                value={filtroHoras}
                onChange={(e) => setFiltroHoras(e.target.value)}
                style={styles.input}
                min="0"
              />
            </div>
            <button
              type="button"
              onClick={() => { setFiltroPrograma(''); setFiltroHoras(''); }}
              style={styles.limpiarFiltrosButton}
            >
              Limpiar filtros
            </button>
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Programa:</label>
            <select 
              name="programa_formacion"
              value={formData.programa_formacion}
              onChange={handleChange}
              style={styles.select}
              required
            >
              <option value="">Seleccione...</option>
              {getProgramasFiltrados().map(prog => (
                <option key={prog._id} value={prog._id}>
                  {prog.nombre_programa} - {prog.codigo} {prog.duracion_maxima ? `(${prog.duracion_maxima} h)` : ''}
                </option>
              ))}
            </select>
            {getProgramasFiltrados().length === 0 && (
              <div style={styles.sinResultados}>No hay programas que coincidan con los filtros</div>
            )}
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Modalidad:</label>
            <select 
              name="modalidad"
              value={formData.modalidad}
              onChange={handleChange}
              style={styles.select}
              required
            >
              <option value="">Seleccione...</option>
              {modalidades.map(mod => (
                <option key={mod._id} value={mod._id}>
                  {mod.nombre}
                </option>
              ))}
            </select>
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Tipo de Oferta:</label>
            <select 
              name="tipo_oferta"
              value={formData.tipo_oferta}
              onChange={handleChange}
              style={styles.select}
              required
            >
              <option value="">Seleccione...</option>
              {tiposOferta.map(to => (
                <option key={to._id} value={to._id}>
                  {to.nombre}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* CUPOS */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Cupos</h3>
          <div style={styles.formGroup}>
            <label style={styles.label}>Cupo Máximo:</label>
            <input 
              type="number"
              name="cupo_maximo"
              value={formData.cupo_maximo}
              onChange={handleChange}
              style={styles.input}
              placeholder="30"
              min="1"
              required
            />
          </div>
        </div>

        {/* AMBIENTE */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Modelo de Ambiente</h3>
          <div style={styles.formGroup}>
            <label style={styles.label}>Nombre del Ambiente:</label>
            <input 
              type="text"
              name="ambiente.nombre"
              value={formData.ambiente.nombre}
              onChange={handleChange}
              style={styles.input}
              placeholder="Ej: Aula 101"
              required
            />
          </div>
        </div>

        {/* FECHAS */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Fechas</h3>
          <div style={styles.row}>
            <div style={styles.half}>
              <label style={styles.label}>Fecha Inicio:</label>
              <input 
                type="date"
                name="fechas.inicio"
                value={formData.fechas.inicio}
                onChange={handleChange}
                style={styles.input}
                required
              />
            </div>
            <div style={styles.half}>
              <label style={styles.label}>Fecha Fin:</label>
              <input 
                type="date"
                name="fechas.fin"
                value={formData.fechas.fin}
                onChange={handleChange}
                style={styles.input}
                required
              />
            </div>
          </div>
          <button
            type="button"
            onClick={handleRecalcularFechaFin}
            style={styles.recalcularButton}
          >
            🔄 Recalcular fecha fin automáticamente
          </button>
        </div>

        {/* HORARIO - SOLO PARA MODO REGULAR */}
        {modo === 'regular' && (
          <div style={styles.section}>
            <h3 style={styles.sectionTitle}>Horario</h3>
            
            <div style={styles.row}>
              <div style={styles.half}>
                <label style={styles.label}>Hora Inicio:</label>
                <input 
                  type="time"
                  name="horario.hora_inicio"
                  value={formData.horario.hora_inicio}
                  onChange={handleChange}
                  style={styles.input}
                  required
                />
              </div>
              <div style={styles.half}>
                <label style={styles.label}>Hora Fin:</label>
                <input 
                  type="time"
                  name="horario.hora_fin"
                  value={formData.horario.hora_fin}
                  onChange={handleChange}
                  style={styles.input}
                  required
                />
              </div>
            </div>

            <div style={styles.formGroup}>
              <label style={styles.label}>Días:</label>
              <div style={styles.checkboxGroup}>
                {diasSemana.map(dia => (
                  <label key={dia} style={styles.checkboxLabel}>
                    <input 
                      type="checkbox"
                      value={dia}
                      checked={formData.horario.dias.includes(dia)}
                      onChange={handleDiaChange}
                    /> {dia}
                  </label>
                ))}
              </div>
              {horasPrograma > 0 && (horasPorDia <= 0 || formData.horario.dias.length === 0) && (
                <div style={styles.advertencia}>
                  ⚠️ Configure horario y días para calcular la fecha fin automáticamente.
                </div>
              )}
              {horasPorSemana > 0 && (
                <div style={styles.infoCalculo}>
                  <p>📊 Horas por día: <strong>{horasPorDia.toFixed(1)}</strong></p>
                  <p>📅 Horas por semana: <strong>{horasPorSemana.toFixed(1)}</strong></p>
                  <p>⏱️ Duración total del programa: <strong>{horasPrograma}</strong> horas</p>
              {formData.fechas.inicio && formData.fechas.fin && (
                <p>📈 Horas disponibles en el rango: <strong>{calcularHorasEnRango(
                  formData.fechas.inicio,
                  formData.fechas.fin,
                  formData.horario.dias,
                  formData.horario.hora_inicio,
                  formData.horario.hora_fin
                ).toFixed(1)}</strong> horas</p>
              )}
              <p>📆 Semanas necesarias: <strong>{semanasNecesarias}</strong></p>
                  <p style={styles.notaInfo}>
                    * Puedes modificar la fecha fin manualmente si hay festivos o ajustes.
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* UBICACIÓN */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Ubicación</h3>
          
          <div style={styles.formGroup}>
            <label style={styles.label}>Departamento:</label>
            <input 
              type="text"
              name="ubicacion.departamento"
              value={formData.ubicacion.departamento}
              onChange={handleChange}
              style={styles.input}
              placeholder="Cauca"
              required
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Municipio:</label>
            <div className="custom-select-container" style={styles.customSelect}>
              <div 
                style={styles.customSelectHeader}
                onClick={() => setMunicipioAbierto(!municipioAbierto)}
              >
                <span>
                  {municipios.find(m => m._id === formData.ubicacion.municipio)?.nombre || 'Seleccione...'}
                </span>
                <span style={styles.customSelectArrow}>{municipioAbierto ? '▲' : '▼'}</span>
              </div>
              {municipioAbierto && (
                <div style={styles.customSelectDropdown}>
                  <input
                    type="text"
                    placeholder="Buscar municipio..."
                    value={busquedaMunicipio}
                    onChange={(e) => setBusquedaMunicipio(e.target.value)}
                    style={styles.customSelectSearch}
                    autoFocus
                  />
                  <div style={styles.customSelectOptions}>
                    {getMunicipiosFiltradosBusqueda().length === 0 ? (
                      <div style={styles.customSelectNoResults}>No hay resultados</div>
                    ) : (
                      getMunicipiosFiltradosBusqueda().map(mun => (
                        <div
                          key={mun._id}
                          style={styles.customSelectOption}
                          onClick={() => {
                            handleChange({ target: { name: 'ubicacion.municipio', value: mun._id } });
                            setMunicipioAbierto(false);
                            setBusquedaMunicipio('');
                          }}
                        >
                          {mun.nombre}
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>Dirección:</label>
            <input 
              type="text"
              name="ubicacion.direccion"
              value={formData.ubicacion.direccion}
              onChange={handleChange}
              style={styles.input}
              placeholder="Calle 123 #45-67, Barrio Centro"
              required
            />
          </div>
        </div>

        {/* EMPRESA SOLICITANTE */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Empresa Solicitante</h3>
          
          {!mostrarFormularioEmpresa ? (
            <>
              <div style={styles.formGroup}>
                <label style={styles.label}>Seleccionar Empresa:</label>
                <select 
                  name="empresa_solicitante"
                  value={formData.empresa_solicitante}
                  onChange={handleChange}
                  style={styles.select}
                >
                  <option value="">Seleccione una empresa...</option>
                  {empresas.map(emp => (
                    <option key={emp._id} value={emp._id}>
                      {emp.nombre} - NIT: {emp.nit}
                    </option>
                  ))}
                </select>
              </div>
              <button 
                type="button"
                onClick={() => setMostrarFormularioEmpresa(true)}
                style={styles.secondaryButton}
              >
                ➕ Crear Nueva Empresa
              </button>
            </>
          ) : (
            <div style={styles.subSection}>
              <h4 style={styles.subSectionTitle}>Nueva Empresa</h4>
              
              {/* Datos básicos */}
              <div style={styles.formGroup}>
                <label style={styles.label}>Nombre de la Empresa:</label>
                <input
                  type="text"
                  name="nombre"
                  value={nuevaEmpresa.nombre}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="Nombre de la empresa"
                />
              </div>

              <div style={styles.row}>
                <div style={styles.half}>
                  <label style={styles.label}>NIT:</label>
                  <input
                    type="text"
                    name="nit"
                    value={nuevaEmpresa.nit}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="123456789-0"
                  />
                </div>
                <div style={styles.half}>
                  <label style={styles.label}>Fecha Creación:</label>
                  <input
                    type="date"
                    name="fecha_creacion"
                    value={nuevaEmpresa.fecha_creacion}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                  />
                </div>
              </div>

              <div style={styles.row}>
                <div style={styles.half}>
                  <label style={styles.label}>Tipo de Empresa:</label>
                  <select
                    name="tipo_empresa"
                    value={nuevaEmpresa.tipo_empresa}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.select}
                  >
                    <option value="Privada">Privada</option>
                    <option value="Pública">Pública</option>
                    <option value="Mixta">Mixta</option>
                    <option value="ONG">ONG</option>
                    <option value="Fundación">Fundación</option>
                    <option value="Cooperativa">Cooperativa</option>
                    <option value="Otro">Otro</option>
                  </select>
                </div>
                <div style={styles.half}>
                  <label style={styles.label}>Dirección:</label>
                  <input
                    type="text"
                    name="direccion"
                    value={nuevaEmpresa.direccion}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="Dirección completa"
                  />
                </div>
              </div>

              {/* Representante Legal */}
              <h4 style={styles.subSectionTitle}>Representante Legal</h4>
              
              <div style={styles.formGroup}>
                <label style={styles.label}>Nombre Completo:</label>
                <input
                  type="text"
                  name="representante_legal.nombre_completo"
                  value={nuevaEmpresa.representante_legal.nombre_completo}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="Nombre completo del representante"
                />
              </div>

              <div style={styles.row}>
                <div style={styles.half}>
                  <label style={styles.label}>Documento:</label>
                  <input
                    type="text"
                    name="representante_legal.documento_identidad"
                    value={nuevaEmpresa.representante_legal.documento_identidad}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="Documento de identidad"
                  />
                </div>
                <div style={styles.half}>
                  <label style={styles.label}>Teléfono:</label>
                  <input
                    type="text"
                    name="representante_legal.telefono"
                    value={nuevaEmpresa.representante_legal.telefono}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="Teléfono"
                  />
                </div>
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Correo:</label>
                <input
                  type="email"
                  name="representante_legal.correo"
                  value={nuevaEmpresa.representante_legal.correo}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="correo@ejemplo.com"
                />
              </div>

              {/* Contacto en la Empresa */}
              <h4 style={styles.subSectionTitle}>Contacto en la Empresa</h4>
              
              <div style={styles.formGroup}>
                <label style={styles.label}>Nombre Completo:</label>
                <input
                  type="text"
                  name="contacto.nombre_completo"
                  value={nuevaEmpresa.contacto.nombre_completo}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="Nombre del contacto"
                />
              </div>

              <div style={styles.row}>
                <div style={styles.half}>
                  <label style={styles.label}>Cargo:</label>
                  <input
                    type="text"
                    name="contacto.cargo"
                    value={nuevaEmpresa.contacto.cargo}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="Cargo del contacto"
                  />
                </div>
                <div style={styles.half}>
                  <label style={styles.label}>Teléfono:</label>
                  <input
                    type="text"
                    name="contacto.telefono"
                    value={nuevaEmpresa.contacto.telefono}
                    onChange={handleNuevaEmpresaChange}
                    style={styles.input}
                    placeholder="Teléfono del contacto"
                  />
                </div>
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Correo:</label>
                <input
                  type="email"
                  name="contacto.correo"
                  value={nuevaEmpresa.contacto.correo}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="correo@ejemplo.com"
                />
              </div>

              {/* Número de empleados */}
              <div style={styles.formGroup}>
                <label style={styles.label}>Número de Empleados:</label>
                <input
                  type="number"
                  name="numero_empleados"
                  value={nuevaEmpresa.numero_empleados}
                  onChange={handleNuevaEmpresaChange}
                  style={styles.input}
                  placeholder="Ej: 50"
                  min="1"
                />
              </div>

              {/* Botones */}
              <div style={styles.buttonGroup}>
                <button 
                  type="button"
                  onClick={crearNuevaEmpresa}
                  style={styles.successButton}
                  disabled={loading}
                >
                  {loading ? 'Guardando...' : 'Guardar Empresa'}
                </button>
                <button 
                  type="button"
                  onClick={() => setMostrarFormularioEmpresa(false)}
                  style={styles.cancelButton}
                >
                  Cancelar
                </button>
              </div>
            </div>
          )}
        {!mostrarFormularioEmpresa && (
          <small style={styles.fileHint}>
            {esOfertaCerrada ? '* Empresa obligatoria para oferta cerrada' : 'Empresa opcional para oferta abierta'}
          </small>
        )}

        {/* Campo de carta PDF - siempre visible dentro de la sección empresa */}
        <div style={styles.formGroup}>
          <label style={styles.label}>
            Carta (PDF) {esOfertaCerrada && <span style={{ color: 'red' }}>*</span>}
          </label>
          <div style={styles.fileInputGroup}>
            <input
              type="file"
              id="carta_pdf"
              name="carta_pdf"
              onChange={handleFileChange}
              style={styles.fileInput}
              accept=".pdf"
            />
            {formData.carta_pdf && (
              <div style={styles.fileInfo}>
                <span style={styles.fileName}>{formData.carta_pdf.name}</span>
                <button
                  type="button"
                  onClick={() => {
                    document.getElementById('carta_pdf').value = '';
                    setFormData({...formData, carta_pdf: null});
                  }}
                  style={styles.removeFileButton}
                >
                  ✕
                </button>
              </div>
            )}
          </div>
          <small style={styles.fileHint}>
            Documento PDF de la carta solicitante {esOfertaCerrada ? '(obligatorio)' : '(opcional)'}
          </small>
        </div>
      </div>

        {/* SUBSECTOR ECONÓMICO */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Subsector Económico</h3>
          <div style={styles.formGroup}>
            <label style={styles.label}>Nombre:</label>
            <input 
              type="text"
              name="subsector_economico.nombre"
              value={formData.subsector_economico.nombre}
              onChange={handleChange}
              style={styles.input}
              placeholder="Ej: Tecnologías de la Información"
              required
            />
          </div>
        </div>

        {/* PROGRAMA ESPECIAL */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Programa Especial</h3>
          <div style={styles.formGroup}>
            <select 
              name="programa_especial"
              value={formData.programa_especial}
              onChange={handleChange}
              style={styles.select}
            >
              <option value="">Ninguno</option>
              {programasEspeciales.map(pe => (
                <option key={pe._id} value={pe._id}>
                  {pe.nombre}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* CONVENIO */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Convenio</h3>
          <div style={styles.formGroup}>
            <label style={styles.label}>Nombre del Convenio:</label>
            <input 
              type="text"
              name="convenio.nombre"
              value={formData.convenio.nombre}
              onChange={handleChange}
              style={styles.input}
              placeholder="Nombre del convenio"
              required
            />
          </div>
        </div>

        {/* FORMULARIO CAMPESENA (solo si aplica) */}
        {modo === 'campesena' && (
          <FormularioCampesenaCompleto 
            formData={formData}
            setFormData={setFormData}
            horasPrograma={horasPrograma}
            fechasInicio={formData.fechas.inicio}
            fechasFin={formData.fechas.fin}
          />
        )}

        {/* ARCHIVOS PDF */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Documentos Adjuntos</h3>
          
          <div style={styles.formGroup}>
            <label style={styles.label}>Firma Digital (PDF / PNG / JPG):</label>
            <div style={styles.fileInputGroup}>
              <input
                type="file"
                id="firma_digital_pdf"
                name="firma_digital_pdf"
                onChange={handleFileChange}
                style={styles.fileInput}
                accept=".pdf, image/png, image/jpeg, image/jpg"
              />
              {formData.firma_digital_pdf && (
                <div style={styles.fileInfo}>
                  <span style={styles.fileName}>{formData.firma_digital_pdf.name}</span>
                  <button
                    type="button"
                    onClick={() => {
                      document.getElementById('firma_digital_pdf').value = '';
                      setFormData({...formData, firma_digital_pdf: null});
                    }}
                    style={styles.removeFileButton}
                  >
                    ✕
                  </button>
                </div>
              )}
            </div>
            <small style={styles.fileHint}>Archivo PDF o imagen PNG/JPG con la firma digital</small>
          </div>

        </div>

        <button 
          type="submit" 
          style={loading ? {...styles.submitButton, ...styles.buttonDisabled} : styles.submitButton}
          disabled={loading}
        >
          {loading ? 'Guardando...' : 'Guardar Oferta'}
        </button>
      </form>
    </div>
  );
};

const styles = {
  container: {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px'
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px'
  },
  cambiarModoButton: {
    backgroundColor: '#95a5a6',
    color: 'white',
    padding: '8px 16px',
    border: 'none',
    borderRadius: '4px',
    fontSize: '14px',
    fontWeight: 'bold',
    cursor: 'pointer',
    ':hover': {
      backgroundColor: '#7f8c8d'
    }
  },
  fileInputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px'
  },
  fileInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    padding: '8px 12px',
    backgroundColor: '#ecf0f1',
    borderRadius: '4px'
  },
  fileName: {
    fontSize: '13px',
    color: '#2c3e50',
    flex: 1
  },
  removeFileButton: {
    backgroundColor: 'transparent',
    border: 'none',
    color: '#e74c3c',
    cursor: 'pointer',
    fontSize: '16px',
    fontWeight: 'bold',
    padding: '0 5px'
  },
  title: {
    color: '#2c3e50',
    borderBottom: '3px solid #3498db',
    paddingBottom: '10px',
    marginBottom: '0',
    fontSize: '28px'
  },
  section: {
    backgroundColor: '#f8f9fa',
    padding: '20px',
    borderRadius: '8px',
